public InetSocketAddress getPublicAddressFor(InetAddress dst,int port){
  try {
    logger.logEntry();
    if (!useStun) {
      logger.debug("Stun is disabled, skipping mapped address recovery.");
      return new InetSocketAddress(getLocalHost(dst),port);
    }
    StunAddress mappedAddress=queryStunServer(port);
    InetSocketAddress result=null;
    if (mappedAddress != null)     result=mappedAddress.getSocketAddress();
 else {
      InetAddress localHost=getLocalHost(dst);
      result=new InetSocketAddress(localHost,port);
    }
    if (logger.isDebugEnabled())     logger.debug("Returning mapping for port:" + port + " as follows: "+ result);
    return result;
  }
  catch (java.io.UncheckedIOException | java.lang.SecurityException | java.lang.IllegalArgumentException e) {
    logger.debug("Failed to obtain public address, returning null", e);
    return null;
  }
  finally {
    logger.logExit();
  }
}
